// SPDX-License-Identifier: SHL-0.51

// From latch_scm { git: "https://github.com/pulp-platform/scm.git", version: "1.1.0" }, added async rst and NUM_BYTE->N_EN.

module ita_register_file_1w_multi_port_read_we
#(
    parameter ADDR_WIDTH    = 5,
    parameter DATA_WIDTH    = 32,

    parameter N_READ        = 2,
    parameter N_WRITE       = 1,
    parameter N_EN          = 4
)
(
    input  logic                                 clk,
    input  logic                                 rst_n,

    // Read port
    input  logic [N_READ-1:0]                    ReadEnable,
    input  logic [N_READ-1:0][ADDR_WIDTH-1:0]    ReadAddr,
    output logic [N_READ-1:0][DATA_WIDTH-1:0]    ReadData,

    // Write port
    input  logic                                 WriteEnable,
    input  logic [ADDR_WIDTH-1:0]                WriteAddr,
    input  logic [N_EN-1:0][DATA_WIDTH/N_EN-1:0] WriteData,
    input  logic [N_EN-1:0]                      WriteSelect
);

    localparam    NUM_WORDS = 2**ADDR_WIDTH;

    // Read address register, located at the input of the address decoder
    logic [N_READ-1:0][ADDR_WIDTH-1:0]                         RAddrRegxDP;
    logic [N_READ-1:0][NUM_WORDS-1:0]                          RAddrOneHotxD;

    logic [N_EN-1:0][DATA_WIDTH/N_EN-1:0]          MemContentxDP[NUM_WORDS];

    logic [NUM_WORDS-1:0][N_EN-1:0]                WAddrOneHotxD;
    logic [NUM_WORDS-1:0][N_EN-1:0]                ClocksxC;
    logic [N_EN-1:0][DATA_WIDTH/N_EN-1:0]          WDataIntxD;

    logic                                          clk_int;

    int unsigned i;
    int unsigned j;
    int unsigned k;
    int unsigned l;
    int unsigned m;

    genvar       x;
    genvar       y;
    genvar       z;

    cluster_clock_gating CG_WE_GLOBAL
    (
        .clk_o     ( clk_int        ),
        .en_i      ( WriteEnable    ),
        .test_en_i ( 1'b0           ),
        .clk_i     ( clk            )
    );

    //-----------------------------------------------------------------------------
    //-- READ : Read address register
    //-----------------------------------------------------------------------------

    generate
        for(z=0; z<N_READ; z++ )
        begin
            always_ff @(posedge clk, negedge rst_n)
            begin : p_RAddrReg
              if(rst_n == 1'b0)
              begin
                  RAddrRegxDP[z] <= '0;
              end
              else
              if( ReadEnable[z] )
                RAddrRegxDP[z] <= ReadAddr[z];
            end



    //-----------------------------------------------------------------------------
    //-- READ : Read address decoder RAD
    //-----------------------------------------------------------------------------
            always @(*)
            begin : p_RAD
              RAddrOneHotxD[z] = '0;
              RAddrOneHotxD[z][RAddrRegxDP[z]] = 1'b1;
            end
            assign ReadData[z] = MemContentxDP[RAddrRegxDP[z]];

        end
    endgenerate

    //-----------------------------------------------------------------------------
    //-- WRITE : Write Address Decoder (WAD), combinatorial process
    //-----------------------------------------------------------------------------
    always_comb
    begin : p_WAD
      for(i=0; i<NUM_WORDS; i++)
        begin : p_WordIter
            for(j=0; j<N_EN; j++)
              begin : p_ByteIter
                if ( (WriteEnable == 1'b1 ) && (WriteSelect[j] == 1'b1) &&  (WriteAddr == i) )
                  WAddrOneHotxD[i][j] = 1'b1;
                else
                  WAddrOneHotxD[i][j] = 1'b0;
              end
        end
    end



    //-----------------------------------------------------------------------------
    //-- WRITE : Clock gating (if integrated clock-gating cells are available)
    //-----------------------------------------------------------------------------
    generate
    for(x=0; x<NUM_WORDS; x++)
      begin : CG_CELL_WORD_ITER
          for(y=0; y<N_EN; y++)
            begin : CG_CELL_BYTE_ITER
                cluster_clock_gating CG_Inst
                (
                  .clk_o(ClocksxC[x][y]),
                  .en_i(WAddrOneHotxD[x][y]),
                  .test_en_i(1'b0),
                  .clk_i(clk_int)
                );
            end
      end
    endgenerate




    //-----------------------------------------------------------------------------
    // WRITE : SAMPLE INPUT DATA
    //---------------------------------------------------------------------------
    always_ff @(posedge clk, negedge rst_n)
    begin : sample_waddr
      if(rst_n == 1'b0)
      begin
          WDataIntxD <= '0;
      end
      else
      for(m=0; m<N_EN; m++)
        begin
            if(WriteEnable & WriteSelect[m])
              WDataIntxD[m] <= WriteData[m];
        end
    end





    //-----------------------------------------------------------------------------
    //-- WRITE : Write operation
    //-----------------------------------------------------------------------------
    //-- Generate M = WORDS sequential processes, each of which describes one
    //-- word of the memory. The processes are synchronized with the clocks
    //-- ClocksxC(i), i = 0, 1, ..., M-1
    //-- Use active low, i.e. transparent on low latches as storage elements
    //-- Data is sampled on rising clock edge


    always_latch
    begin : latch_wdata
      for(k=0; k<NUM_WORDS; k++)
        begin : w_WordIter
            for(l=0; l<N_EN; l++)
              begin : w_ByteIter
                if( ClocksxC[k][l] == 1'b1)
                  MemContentxDP[k][l] = WDataIntxD[l];
              end
        end
    end


endmodule


// ============================================================================
// ITA dot product
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_dotp.sv
// ============================================================================
// Copyright 2020 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51


/**
  DotP submodule.
  Calculates the dot product of two 8-bit vector of size M.
  */

module ita_dotp #(
    parameter integer M  = 64,
    parameter integer WI = 8,
    parameter integer WO = 26,
    parameter integer WS = WI + 1
) (
    input  logic signed [WS*M-1:0]     inp1_i,
    input  logic signed [WI*M-1:0]     inp2_i,
    output logic signed [  WO-1:0]     oup_o
);

    logic signed [WO-1:0] int_dotp[0:M-1]; // intermediate dotproducts

    assign int_dotp[0] = signed'(inp1_i[0 +: WS]) * signed'(inp2_i[0 +: WI]);

    generate
        for (genvar i = 1; i < M; i = i + 1) begin: dotp_loop
            assign int_dotp[i] = signed'(int_dotp[i-1]) + signed'(inp1_i[WS*i +: WS]) * signed'(inp2_i[WI*i +: WI]);
        end
    endgenerate

    assign oup_o = int_dotp[M-1];

endmodule


// ============================================================================
// ITA accumulator
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_accumulator.sv
// ============================================================================
// Copyright 2020 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51

module ita_accumulator
  import ita_package::*;
#(
  parameter LATCH_BUFFER = 0
)(
  input  logic  clk_i     ,
  input  logic  rst_ni    ,
  input  logic  calc_en_i ,
  input  logic  calc_en_q_i,
  input  logic  first_tile_i,
  input  logic  first_tile_q_i,
  input  logic  last_tile_i,
  input  logic  last_tile_q_i,
  input  oup_t  oup_i     ,
  input  bias_t inp_bias_i,
  output oup_t  result_o
);

  logic  read_en;
  logic [$clog2(M*M/N)-1:0] read_addr;
  oup_t read_data, read_data_unused;
  logic write_en;
  logic [$clog2(M*M/N)-1:0] write_addr;
  oup_t write_data;
  logic [$clog2(M*M/N)-1:0] read_addr_d, read_addr_q, write_addr_d, write_addr_q;

  oup_t result_d, result_q;

  assign result_o = result_q;

  always_comb begin
    read_addr_d    = read_addr_q;
    write_addr_d   = write_addr_q;
    result_d       = '0;
    read_en        = 1'b0;
    read_addr      = read_addr_q;
    write_en       = 1'b0;
    write_data     = '0;
    write_addr     = write_addr_q;

    if (calc_en_i && !first_tile_i) begin
      read_en = 1'b1;
      read_addr_d = read_addr_q + 1;
    end
    if (calc_en_q_i) begin
      if (first_tile_q_i && last_tile_q_i) begin
        for (int i = 0; i < N; i++) begin
          result_d[i] = oup_i[i] + WO'(signed'(inp_bias_i[i]));
        end
      end else if (first_tile_q_i) begin
        write_en = 1'b1;
        write_addr_d = write_addr_q + 1;
        for (int i = 0; i < N; i++) begin
          write_data[i] = oup_i[i];
        end
      end else if (last_tile_q_i) begin
        for (int i = 0; i < N; i++) begin
          result_d[i] = oup_i[i] + read_data[i] + WO'(signed'(inp_bias_i[i]));
        end
      end else begin
        write_en = 1'b1;
        write_addr_d = write_addr_q + 1;
        for (int i = 0; i < N; i++) begin
          write_data[i] = oup_i[i] + read_data[i];
        end
      end
    end
  end

  always_ff @(posedge clk_i, negedge rst_ni) begin
    if (!rst_ni) begin
      read_addr_q    <= '0;
      write_addr_q   <= '0;
      result_q       <= '0;
    end else begin
      read_addr_q    <= read_addr_d;
      write_addr_q   <= write_addr_d;
      result_q       <= result_d;
    end
  end

  if (LATCH_BUFFER) begin : partialsum_buffer_latch
    register_file_1w_multi_port_read #(
      .ADDR_WIDTH($clog2(M*M/N)),
      .DATA_WIDTH(N*WO),
      .N_READ    (1     ),
      .N_WRITE   (1     )
    ) i_partialsum_buffer (
      .clk        (clk_i       ),
      .rst_n      (rst_ni      ),
      .test_en_i  (1'b0        ),

      .ReadEnable (read_en     ),
      .ReadAddr   (read_addr   ),
      .ReadData   (read_data   ),

      .WriteEnable(write_en    ),
      .WriteAddr  (write_addr  ),
      .WriteData  (write_data  )
    );
  end else begin : partialsum_buffer_sram
    tc_sram #(
      .NumWords (M*M/N),
      .DataWidth (N*WO),
      .ByteWidth (8),
      .NumPorts (2),
      .Latency (1)
    ) i_partialsum_buffer (
      .clk_i,
      .rst_ni,
      .req_i ({write_en, read_en}),
      .we_i ({1'b1, 1'b0}),
      .addr_i ({write_addr, read_addr}),
      .wdata_i ({write_data, {(N*WO){1'b0}}}),
      .be_i ({{(N*WO/8){1'b1}}, {(N*WO/8){1'b0}}}),
      .rdata_o ({read_data_unused, read_data})
    );
  end

endmodule


// ============================================================================
// ITA max finder
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_max_finder.sv
// ============================================================================
// Copyright 2020 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51

module ita_max_finder
  import ita_package::*;
(
  input  logic         clk_i     ,
  input  logic         rst_ni    ,
  // Input
  input  requant_oup_t x_i       ,
  input  requant_t     prev_max_i,
  output requant_t     max_o     ,
  output requant_t     max_diff_o
);

  // find maximum
  requant_t [N/2-1:0] max_tmp;
  requant_t [N/4-1:0] max_tmp2;
  requant_t [N/8-1:0] max_tmp3;
  requant_t max_tmp4;

  always_comb begin

    for (int i = 0; i < N/2; i++) begin
      if (x_i[2*i]>x_i[2*i+1])
        max_tmp[i] = x_i[2*i];
      else
        max_tmp[i] = x_i[2*i+1];
    end

    for (int i = 0; i < N/4; i++) begin
      if (max_tmp[2*i]>max_tmp[2*i+1])
        max_tmp2[i] = max_tmp[2*i];
      else
        max_tmp2[i] = max_tmp[2*i+1];
    end

    for (int i = 0; i < N/8; i++) begin
      if (max_tmp2[2*i]>max_tmp2[2*i+1])
        max_tmp3[i] = max_tmp2[2*i];
      else
        max_tmp3[i] = max_tmp2[2*i+1];
    end

    if (max_tmp3[0]>max_tmp3[1])
      max_tmp4 = max_tmp3[0];
    else
      max_tmp4 = max_tmp3[1];

    if (prev_max_i>max_tmp4) begin
      max_o = prev_max_i;
      max_diff_o = '0;
    end else begin
      max_o = max_tmp4;
      max_diff_o = max_o-prev_max_i;
    end

  end

endmodule


// ============================================================================
// ITA serial divider
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_serdiv.sv
// ============================================================================
// Copyright 2018 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51
//
// Author: Michael Schaffner <schaffner@iis.ee.ethz.ch>, ETH Zurich
//         Andreas Traber    <traber@iis.ee.ethz.ch>, ETH Zurich
//
// Date: 18.10.2018
// Description: simple 64bit serial divider
// Modified for ITA

module ita_serdiv #(
  parameter WIDTH       = 32
) (
  input  logic                      clk_i,
  input  logic                      rst_ni,
  // input IF
  input  logic [WIDTH-1:0]          op_a_i,
  input  logic [WIDTH-1:0]          op_b_i,
  input  logic [1:0]                opcode_i, // 0: udiv, 2: urem, 1: div, 3: rem
  // handshake
  input  logic                      in_vld_i, // there is a cycle delay from in_rdy_o->in_vld_i, see issue_read_operands.sv stage
  output logic                      in_rdy_o,
  input  logic                      flush_i,
  // output IF
  output logic                      out_vld_o,
  input  logic                      out_rdy_i,
  output logic [WIDTH-1:0]          res_o
);

/////////////////////////////////////
// signal declarations
/////////////////////////////////////

  enum logic [1:0] {IDLE, DIVIDE, FINISH} state_d, state_q;

  logic [WIDTH-1:0]       res_q, res_d;
  logic [WIDTH-1:0]       op_a_q, op_a_d;
  logic [WIDTH-1:0]       op_b_q, op_b_d;
  logic                   op_a_sign, op_b_sign;
  logic                   op_b_zero, op_b_zero_q, op_b_zero_d;

  logic rem_sel_d, rem_sel_q;
  logic comp_inv_d, comp_inv_q;
  logic res_inv_d, res_inv_q;

  logic [WIDTH-1:0] add_mux;
  logic [WIDTH-1:0] add_out;
  logic [WIDTH-1:0] add_tmp;
  logic [WIDTH-1:0] b_mux;
  logic [WIDTH-1:0] out_mux;

  logic [$clog2(WIDTH+1)-1:0] cnt_q, cnt_d;
  logic cnt_zero;

  logic [WIDTH-1:0] lzc_a_input, lzc_b_input, op_b;
  logic [$clog2(WIDTH)-1:0] lzc_a_result, lzc_b_result;
  logic [$clog2(WIDTH+1)-1:0] shift_a;
  logic [$clog2(WIDTH+1):0] div_shift;

  logic a_reg_en, b_reg_en, res_reg_en, ab_comp, pm_sel, load_en;
  logic lzc_a_no_one, lzc_b_no_one;
  logic div_res_zero_d, div_res_zero_q;


/////////////////////////////////////
// align the input operands
// for faster division
/////////////////////////////////////

  assign op_b_zero = (op_b_i == 0);
  assign op_a_sign = op_a_i[$high(op_a_i)];
  assign op_b_sign = op_b_i[$high(op_b_i)];

  assign lzc_a_input = (opcode_i[0] & op_a_sign) ? {~op_a_i, 1'b0} : op_a_i;
  assign lzc_b_input = (opcode_i[0] & op_b_sign) ? ~op_b_i         : op_b_i;

  lzc #(
    .MODE    ( 1          ), // count leading zeros
    .WIDTH   ( WIDTH      )
  ) i_lzc_a (
    .in_i    ( lzc_a_input  ),
    .cnt_o   ( lzc_a_result ),
    .empty_o ( lzc_a_no_one )
  );

  lzc #(
    .MODE    ( 1          ), // count leading zeros
    .WIDTH   ( WIDTH      )
  ) i_lzc_b (
    .in_i    ( lzc_b_input  ),
    .cnt_o   ( lzc_b_result ),
    .empty_o ( lzc_b_no_one )
  );

  assign shift_a      = (lzc_a_no_one) ? WIDTH : lzc_a_result;
  assign div_shift    = (lzc_b_no_one) ? WIDTH : lzc_b_result-shift_a;

  assign op_b         = op_b_i <<< $unsigned(div_shift);

  // the division is zero if |opB| > |opA| and can be terminated
  assign div_res_zero_d = (load_en) ? ($signed(div_shift) < 0) : div_res_zero_q;

/////////////////////////////////////
// Datapath
/////////////////////////////////////

  assign pm_sel      = load_en & ~(opcode_i[0] & (op_a_sign ^ op_b_sign));

  // muxes
  assign add_mux     = (load_en)   ? op_a_i  : op_b_q;

  // attention: logical shift by one in case of negative operand B!
  assign b_mux       = (load_en)   ? op_b : {comp_inv_q, (op_b_q[$high(op_b_q):1])};

  // in case of bad timing, we could output from regs -> needs a cycle more in the FSM
  assign out_mux     = (rem_sel_q) ? op_a_q : res_q;
  // assign out_mux     = (rem_sel_q) ? op_a_d : res_d;

  // invert if necessary
  assign res_o       = (res_inv_q) ? -$signed(out_mux) : out_mux;

  // main comparator
  assign ab_comp     = ((op_a_q == op_b_q) | ((op_a_q > op_b_q) ^ comp_inv_q)) & ((|op_a_q) | op_b_zero_q);

  // main adder
  assign add_tmp     = (load_en) ? 0 : op_a_q;
  assign add_out     = (pm_sel)  ? add_tmp + add_mux : add_tmp - $signed(add_mux);

/////////////////////////////////////
// FSM, counter
/////////////////////////////////////

  assign cnt_zero = (cnt_q == 0);
  assign cnt_d    = (load_en)   ? div_shift  :
                    (~cnt_zero) ? cnt_q - 1  : cnt_q;

  always_comb begin : p_fsm
    // default
    state_d        = state_q;
    in_rdy_o       = 1'b0;
    out_vld_o      = 1'b0;
    load_en        = 1'b0;
    a_reg_en       = 1'b0;
    b_reg_en       = 1'b0;
    res_reg_en     = 1'b0;

    unique case (state_q)
      IDLE: begin
        in_rdy_o    = 1'b1;

        if (in_vld_i) begin
          // in_rdy_o  = 1'b0;// there is a cycle delay until the valid signal is asserted by the id stage
          a_reg_en  = 1'b1;
          b_reg_en  = 1'b1;
          load_en   = 1'b1;
          state_d   = DIVIDE;
        end
      end
      DIVIDE: begin
        if(~div_res_zero_q) begin
          a_reg_en     = ab_comp;
          b_reg_en     = 1'b1;
          res_reg_en   = 1'b1;
        end
        // can end the division now if the result is clearly 0
        if(div_res_zero_q) begin
          out_vld_o = 1'b1;
          state_d   = FINISH;
          if(out_rdy_i) begin
            // in_rdy_o = 1'b1;// there is a cycle delay until the valid signal is asserted by the id stage
            state_d  = IDLE;
          end
        end else if (cnt_zero) begin
          state_d   = FINISH;
        end
      end
      FINISH: begin
        out_vld_o = 1'b1;

        if (out_rdy_i) begin
          // in_rdy_o = 1'b1;// there is a cycle delay until the valid signal is asserted by the id stage
          state_d  = IDLE;
        end
      end
      default : state_d = IDLE;
    endcase

    if (flush_i) begin
        in_rdy_o   = 1'b0;
        out_vld_o  = 1'b0;
        a_reg_en   = 1'b0;
        b_reg_en   = 1'b0;
        load_en    = 1'b0;
        state_d    = IDLE;
    end
  end

/////////////////////////////////////
// regs, flags
/////////////////////////////////////

  // get flags
  assign rem_sel_d    = (load_en) ? opcode_i[1]               : rem_sel_q;
  assign comp_inv_d   = (load_en) ? opcode_i[0] & op_b_sign   : comp_inv_q;
  assign op_b_zero_d  = (load_en) ? op_b_zero                 : op_b_zero_q;
  assign res_inv_d    = (load_en) ? (~op_b_zero | opcode_i[1]) & opcode_i[0] & (op_a_sign ^ op_b_sign) : res_inv_q;

  assign op_a_d   = (a_reg_en)   ? add_out : op_a_q;
  assign op_b_d   = (b_reg_en)   ? b_mux   : op_b_q;
  assign res_d    = (load_en)   ? '0       :
                    (res_reg_en) ? {res_q[$high(res_q)-1:0], ab_comp} : res_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin : p_regs
    if (~rst_ni) begin
      state_q        <= IDLE;
      op_a_q         <= '0;
      op_b_q         <= '0;
      res_q          <= '0;
      cnt_q          <= '0;
      rem_sel_q      <= 1'b0;
      comp_inv_q     <= 1'b0;
      res_inv_q      <= 1'b0;
      op_b_zero_q    <= 1'b0;
      div_res_zero_q <= 1'b0;
    end else begin
      state_q        <= state_d;
      op_a_q         <= op_a_d;
      op_b_q         <= op_b_d;
      res_q          <= res_d;
      cnt_q          <= cnt_d;
      rem_sel_q      <= rem_sel_d;
      comp_inv_q     <= comp_inv_d;
      res_inv_q      <= res_inv_d;
      op_b_zero_q    <= op_b_zero_d;
      div_res_zero_q <= div_res_zero_d;
    end
  end

endmodule


// ============================================================================
// ITA GELU
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_gelu.sv
// ============================================================================
// Copyright 2024 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51

module ita_gelu
  import ita_package::*;
  (
    input logic clk_i,
    input logic rst_ni,
    input gelu_const_t b_i,
    input gelu_const_t c_i,
    input logic calc_en_i,
    input logic calc_en_q_i,
    input requant_t  data_i,
    output gelu_out_t data_o
  );

  logic erf_sgn_d, erf_sgn_q1;
  gelu_const_t c_q1;
  gelu_const_t data_sign_ext, erf_abs, erf_clipped, poly_d;
  gelu_out_t erf_L_q1, gelu_erf_q1, gelu_sum_q1;
  gelu_out_t gelu_out_q1, gelu_out_q2;
  gelu_out_t poly_sq_d, poly_sq_q1;
  requant_t data_q1;

  always_comb begin : first_stage
    data_sign_ext = {{GELU_CONSTANTS_WIDTH-WI{data_i[WI-1]}}, data_i};

    erf_sgn_d     = data_i < 0;
    erf_abs       = erf_sgn_d ? -data_sign_ext : data_sign_ext;
    erf_clipped   = erf_abs > -b_i ? -b_i : erf_abs;

    poly_d        = erf_clipped + b_i;
    poly_sq_d     = (calc_en_i) ?  poly_d * poly_d : poly_sq_q1;
  end

  always_comb begin : second_stage
    erf_L_q1    = poly_sq_q1 + c_q1;
    gelu_erf_q1 = erf_sgn_q1 ? -erf_L_q1 : erf_L_q1;
    gelu_sum_q1 = gelu_erf_q1 + c_q1;
    gelu_out_q1 = (calc_en_q_i) ? data_q1 * gelu_sum_q1 : gelu_out_q2;
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      c_q1        <= '0;
      data_q1     <= '0;
      erf_sgn_q1  <= '0;
      poly_sq_q1  <= '0;
      gelu_out_q2 <= '0;
    end else begin
      c_q1        <= c_i;
      data_q1     <= data_i;
      erf_sgn_q1  <= erf_sgn_d;
      poly_sq_q1  <= poly_sq_d;
      gelu_out_q2 <= gelu_out_q1;
    end
  end

  assign data_o = gelu_out_q2;

endmodule


