// ============================================================================
// ITA softmax
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_softmax.sv
// ============================================================================
// Copyright 2021 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51


module ita_softmax
  import ita_package::*;
(
  // Clock and reset
  input  logic                                clk_i,
  input  logic                                rst_ni,
  input  ctrl_t                               ctrl_i,
  input  step_e                               step_i,
  input  logic                                calc_en_i,
  input  requant_oup_t                        requant_oup_i,
  input  logic                                calc_stream_soft_en_i,
  output counter_t                            soft_addr_div_o,
  output logic                                softmax_done_o,
  output logic                                pop_softmax_fifo_o,
  input  inp_t                                inp_i,
  output inp_t                                inp_stream_soft_o,
  output logic [SoftmaxAccDataWidth-1:0]      div_inp_o,
  output logic [NumDiv-1:0]                   div_valid_o,
  input  logic [NumDiv-1:0]                   div_ready_i,
  input  logic [NumDiv-1:0]                   div_valid_i,
  output logic [NumDiv-1:0]                   div_ready_o,
  input  logic [NumDiv-1:0][DividerWidth-1:0] div_oup_i,
  output logic [1:0]                          read_acc_en_o,
  output logic [1:0][InputAddrWidth-1:0]      read_acc_addr_o,
  input  logic [1:0][SoftmaxAccDataWidth-1:0] read_acc_data_i,
  output logic                                write_acc_en_o,
  output logic [InputAddrWidth-1:0]           write_acc_addr_o,
  output logic [SoftmaxAccDataWidth-1:0]      write_acc_data_o,
  output requant_t                            prev_max_o,
  input  requant_t                            max_i,
  output requant_oup_t                        max_o,
  output logic [1:0]                          read_max_en_o,
  output logic [1:0][InputAddrWidth-1:0]      read_max_addr_o,
  input  requant_t [1:0]                      read_max_data_i,
  output logic                                write_max_en_o,
  output logic [InputAddrWidth-1:0]           write_max_addr_o,
  output requant_t                            write_max_data_o
);

  counter_t tile_d, tile_q1, tile_q2, tile_q3, tile_q4;
  counter_t count_d, count_q1, count_q2, count_q3, count_q4;

  logic unsigned [SoftmaxAccDataWidth-1:0] exp_sum_d, exp_sum_q;
  counter_t count_soft_d, count_soft_q;

  counter_t count_div_d, count_div_q, addr_div_d, addr_div_q;
  logic [NumDiv-1:0] div_read_d, div_read_q, div_write_d, div_write_q;

  requant_oup_t requant_oup_q;
  requant_t max_d, max_q;

  logic unsigned [N-1:0][WI-SoftmaxShift:0] shift_d, shift_q;
  logic [N-1:0][WI-1:0] shift_diff;
  logic unsigned [WI-SoftmaxShift:0] shift_sum_d, shift_sum_q;
  logic [WI-1:0] max_diff;
  logic unsigned [M-1:0][WI-SoftmaxShift:0] shift_inp;
  logic [M-1:0][WI-1:0] shift_inp_diff;

  logic calc_stream_soft_en_q;
  logic calc_en_d, calc_en_q1, calc_en_q2, calc_en_q3;

  // FIFO signals
  logic        fifo_full, fifo_empty, push_to_fifo, pop_from_fifo;
  logic [SoftmaxAccDataWidth-1:0]  data_to_fifo, data_from_fifo;
  soft_fifo_usage_t fifo_usage  ;

  assign pop_softmax_fifo_o = pop_from_fifo;
  assign soft_addr_div_o    = addr_div_q;

  always_comb begin
    tile_d            = tile_q1;
    count_d           = count_q1;
    count_soft_d      = count_soft_q;
    count_div_d       = count_div_q;
    div_read_d        = div_read_q;
    div_write_d       = div_write_q;
    addr_div_d        = addr_div_q;
    calc_en_d         = 1'b0;
    exp_sum_d         = '0;
    read_acc_en_o     = 0;
    read_acc_addr_o   = '0;
    write_acc_en_o    = 0;
    write_acc_addr_o  = '0;
    write_acc_data_o  = '0;
    read_max_en_o     = '0;
    read_max_addr_o   = '0;
    write_max_en_o    = 0;
    write_max_addr_o  = '0;
    write_max_data_o  = '0;
    push_to_fifo      = 0;
    pop_from_fifo     = 0;
    data_to_fifo      = '0;
    div_inp_o         = data_from_fifo;
    div_valid_o       = 0;
    div_ready_o       = 0;
    prev_max_o        = '0;
    max_o             = '0;
    max_d             = max_q;
    shift_d           = '0;
    shift_diff        = '0;
    shift_sum_d       = '0;
    max_diff          = '0;
    shift_inp         = '0;
    shift_inp_diff    = '0;
    inp_stream_soft_o = '0;
    softmax_done_o    = 0;

    //************ Accumulation ************//
    case (step_i)
      default : begin
        tile_d      = '0;
        count_d     = '0;
      end
      QK : begin
        //************ Pipeline Stage 0 ************//
        if (calc_en_i) begin // After first part of the row check previous max
          calc_en_d = 1'b1;
          count_d = count_q1 + 1;
          if (count_q1 == M*M/N-1) begin
            tile_d  = tile_q1 + 1;
            count_d = '0;
          end
          if (tile_q1 != '0 || count_q1 >= M) begin
            read_max_en_o[0]   = 1;
            read_max_addr_o[0] = count_q1;
          end
        end
      end
    endcase

    //************ Pipeline Stage 1 ************//
    if (calc_en_q1) begin // Find max and accumulate
      max_o = requant_oup_q;
      max_d = max_i;
      for (int i = 0; i < N; i++) begin
        shift_diff[i] = max_i - requant_oup_q[i];
        shift_d[i]    = unsigned'(shift_diff[i]) >> SoftmaxShift;
        if (SoftmaxShift != 0 && shift_diff[i][SoftmaxShift-1])
          shift_d[i] = (unsigned'(shift_diff[i]) >> SoftmaxShift) + 1;
      end
      if (tile_q2 != '0 || count_q2>=M) begin // If not first part of the first row, normalize previous sum
        read_acc_en_o[0]   = 1;
        read_acc_addr_o[0] = count_q2;
        prev_max_o  = read_max_data_i[0];
        max_diff    = max_i - prev_max_o;
        shift_sum_d = max_diff >> SoftmaxShift;
        if (SoftmaxShift != 0 && max_diff[SoftmaxShift-1])
          shift_sum_d = (max_diff >> SoftmaxShift) + 1;
      end else begin
        prev_max_o = 8'h80;
      end
    end

    //************ Pipeline Stage 2 ************//
    if (calc_en_q2) begin // Write max and accumulate
      write_max_en_o   = 1;
      write_max_addr_o = count_q3;
      write_max_data_o = max_q;
      for (int i = 0; i < N; i++) begin
        exp_sum_d += unsigned'(9'h100)>>shift_q[i];
      end
      if (tile_q3 != '0 || count_q3>=M) begin // If not first part of the first row
        exp_sum_d += ( unsigned'(read_acc_data_i[0]) >> shift_sum_q);
      end
    end

    //************ Pipeline Stage 3 ************//
    // Write accumulated sum or send to division fifo
    if (calc_en_q3) begin // Write accumulated sum or send to division fifo
      if (count_q4>=(M*M/N-M) && tile_q4 == ctrl_i.tile_s-1) begin // If last tile and last part of the row
        // Main controller checks if FIFO is full
        push_to_fifo = 1;
        data_to_fifo = exp_sum_q;
      end else begin
        write_acc_en_o   = 1;
        write_acc_addr_o = count_q4;
        write_acc_data_o = exp_sum_q;
      end
    end

    //************** Division **************//
      div_valid_o[div_read_q]  = !fifo_empty;
      div_ready_o[div_write_q] = 1;
      if (div_valid_o[div_read_q] && div_ready_i[div_read_q]) begin
        pop_from_fifo   = 1;
        count_div_d = count_div_q + 1;
        div_read_d  = div_read_q + 1;
        if (div_read_d==NumDiv)
          div_read_d = 0;
      end
      if (div_valid_i[div_write_q]) begin
        write_acc_en_o   = 1;
        write_acc_addr_o = addr_div_q;
        addr_div_d       = addr_div_q + 1;
        write_acc_data_o = div_oup_i[div_write_q];
        div_write_d      = div_write_q + 1;
        if (div_write_d==NumDiv)
          div_write_d = 0;
        if (addr_div_d==M) begin
          addr_div_d     = '0;
          count_div_d    = '0;
          softmax_done_o = 1;
        end
      end

    //*********** Stream Softmax ***********//
    // Main controller checks if division is ready
    if (calc_stream_soft_en_i) begin
      count_soft_d    = count_soft_q + 1;
      read_acc_en_o[1]   = 1;
      read_acc_addr_o[1] = count_soft_q[5:0];
      read_max_en_o[1]   = 1;
      read_max_addr_o[1] = count_soft_q[5:0];
      if (count_soft_d == M*M/N) begin
        count_soft_d = '0;
      end
    end
    if (calc_stream_soft_en_q) begin
      for (int i = 0; i < M; i++) begin
        shift_inp_diff[i] = read_max_data_i[1]-inp_i[i];
        shift_inp[i]      = unsigned'(shift_inp_diff[i]) >> SoftmaxShift;
        if (SoftmaxShift != 0 && shift_inp_diff[i][SoftmaxShift-1])
          shift_inp[i] = (unsigned'(shift_inp_diff[i]) >> SoftmaxShift) + 1;
        inp_stream_soft_o[i] = read_acc_data_i[1] >> shift_inp[i];
      end
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if(~rst_ni) begin
      tile_q4               <= '0;
      tile_q3               <= '0;
      tile_q2               <= '0;
      tile_q1               <= '0;
      count_q4              <= M*M/N;
      count_q3              <= M*M/N;
      count_q2              <= M*M/N;
      count_q1               <= M*M/N;
      count_soft_q          <= '0;
      count_div_q           <= '0;
      div_read_q            <= '0;
      div_write_q           <= '0;
      addr_div_q            <= '0;
      exp_sum_q             <= '0;
      requant_oup_q         <= '0;
      max_q                 <= '0;
      calc_stream_soft_en_q <= 0;
      shift_q               <= '0;
      shift_sum_q           <= '0;
    end else begin
      tile_q4               <= tile_q3;
      tile_q3               <= tile_q2;
      tile_q2               <= tile_q1;
      tile_q1               <= tile_d;
      count_q4              <= count_q3;
      count_q3              <= count_q2;
      count_q2              <= count_q1;
      count_q1              <= count_d;
      count_soft_q          <= count_soft_d;
      count_div_q           <= count_div_d;
      div_read_q            <= div_read_d;
      div_write_q           <= div_write_d;
      addr_div_q            <= addr_div_d;
      exp_sum_q             <= exp_sum_d;
      requant_oup_q         <= requant_oup_i;
      max_q                 <= max_d;
      calc_stream_soft_en_q <= calc_stream_soft_en_i;
      shift_q               <= shift_d;
      shift_sum_q           <= shift_sum_d;
    end
  end

  always_ff @(posedge clk_i, negedge rst_ni) begin
    if (!rst_ni) begin
      calc_en_q3 <= 0;
      calc_en_q2 <= 0;
      calc_en_q1 <= 0;
    end else begin
      calc_en_q3 <= calc_en_q2;
      calc_en_q2 <= calc_en_q1;
      calc_en_q1 <= calc_en_d;
    end
  end

  fifo_v3 #(
    .FALL_THROUGH(1'b0               ),
    .DATA_WIDTH  (SoftmaxAccDataWidth),
    .DEPTH       (SoftFifoDepth      )
  ) i_fifo (
    .clk_i     (clk_i         ),
    .rst_ni    (rst_ni        ),
    .flush_i   (1'b0          ),
    .testmode_i(1'b0          ),
    // status flags
    .full_o    (fifo_full     ), // queue is full
    .empty_o   (fifo_empty    ), // queue is empty
    .usage_o   (fifo_usage    ),
    // as long as the queue is not full we can push new data
    .data_i    (data_to_fifo  ),
    .push_i    (push_to_fifo  ),
    // as long as the queue is not empty we can pop new elements
    .data_o    (data_from_fifo),
    .pop_i     (pop_from_fifo )
  );

endmodule : ita_softmax


// ============================================================================
// ITA softmax top
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_softmax_top.sv
// ============================================================================
// Copyright 2020 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51


module ita_softmax_top
  import ita_package::*;
(
  input  logic         clk_i                ,
  input  logic         rst_ni               ,
  input  ctrl_t        ctrl_i               ,
  // Input
  input  requant_oup_t requant_oup_i        ,
  input  step_e        step_i               ,
  input  logic         calc_en_i            ,
  input  inp_t         inp_i                ,
  input  logic         calc_stream_soft_en_i,
  // Output
  output counter_t     soft_addr_div_o      ,
  output logic         softmax_done_o       ,
  output logic         pop_softmax_fifo_o   ,
  output inp_t         inp_stream_soft_o
);

  logic          [1:0]                                       read_acc_en;
  logic          [1:0][SoftmaxAccDataWidth-1:0]              read_acc_data;
  logic          [1:0][     InputAddrWidth-1:0]              read_acc_addr;
  logic                                                      write_acc_en;
  logic          [SoftmaxAccDataWidth-1:0]                   write_acc_data;
  logic          [     InputAddrWidth-1:0]                   write_acc_addr;
  logic          [SoftmaxAccDataWidth-1:0]                   div_inp      ;
  logic          [             NumDiv-1:0]                   div_valid_inp, div_ready_inp;
  logic          [             NumDiv-1:0]                   div_valid_oup, div_ready_oup;
  logic unsigned [             NumDiv-1:0][DividerWidth-1:0] div_oup      ;
  logic unsigned [       DividerWidth-1:0]                   val          ;

  requant_oup_t max_in  ;
  requant_t     prev_max, max_out;

  ita_max_finder i_max_finder (
    .clk_i     (clk_i        ),
    .rst_ni    (rst_ni       ),
    .x_i       (max_in       ),
    .prev_max_i(prev_max     ),
    .max_o     (max_out      ),
    .max_diff_o(/* unused */ )
  );

  logic [1:0]                     read_max_en;
  requant_t [1:0]                 read_max_data;
  logic [1:0][InputAddrWidth-1:0] read_max_addr;

  logic                      write_max_en;
  requant_t                  write_max_data;
  logic [InputAddrWidth-1:0] write_max_addr;

  ita_register_file_1w_multi_port_read #(
    .ADDR_WIDTH(InputAddrWidth),
    .DATA_WIDTH(WI            ),
    .N_READ    (2             ),
    .N_WRITE   (1             )
  ) i_softmax_max_buffer (
    .clk        (clk_i         ),
    .rst_n      (rst_ni        ),
    .test_en_i  (1'b0          ),

    .ReadEnable (read_max_en   ),
    .ReadAddr   (read_max_addr ),
    .ReadData   (read_max_data ),

    .WriteEnable(write_max_en  ),
    .WriteAddr  (write_max_addr),
    .WriteData  (write_max_data)
  );

  ita_softmax i_softmax (
    .clk_i                (clk_i                ),
    .rst_ni               (rst_ni               ),
    .ctrl_i               (ctrl_i               ),
    .step_i               (step_i               ),
    .calc_en_i            (calc_en_i            ),
    .requant_oup_i        (requant_oup_i        ),

    .calc_stream_soft_en_i(calc_stream_soft_en_i),
    .soft_addr_div_o      (soft_addr_div_o      ),
    .softmax_done_o       (softmax_done_o       ),
    .pop_softmax_fifo_o   (pop_softmax_fifo_o   ),
    .inp_i                (inp_i                ),
    .inp_stream_soft_o    (inp_stream_soft_o    ),

    .div_inp_o            (div_inp              ),
    .div_valid_o          (div_valid_inp        ),
    .div_ready_i          (div_ready_inp        ),
    .div_valid_i          (div_valid_oup        ),
    .div_ready_o          (div_ready_oup        ),
    .div_oup_i            (div_oup              ),

    .read_acc_en_o        (read_acc_en          ),
    .read_acc_addr_o      (read_acc_addr        ),
    .read_acc_data_i      (read_acc_data        ),

    .write_acc_en_o       (write_acc_en         ),
    .write_acc_addr_o     (write_acc_addr       ),
    .write_acc_data_o     (write_acc_data       ),

    .prev_max_o           (prev_max             ),
    .max_i                (max_out              ),
    .max_o                (max_in               ),

    .read_max_en_o        (read_max_en          ),
    .read_max_addr_o      (read_max_addr        ),
    .read_max_data_i      (read_max_data        ),

    .write_max_en_o       (write_max_en         ),
    .write_max_addr_o     (write_max_addr       ),
    .write_max_data_o     (write_max_data       )
  );

  ita_register_file_1w_multi_port_read #(
    .ADDR_WIDTH(InputAddrWidth     ),
    .DATA_WIDTH(SoftmaxAccDataWidth),
    .N_READ    (2                  ),
    .N_WRITE   (1                  )
  ) i_softmax_acc_buffer (
    .clk        (clk_i         ),
    .rst_n      (rst_ni        ),
    .test_en_i  (1'b0          ),

    .ReadEnable (read_acc_en   ),
    .ReadAddr   (read_acc_addr ),
    .ReadData   (read_acc_data ),

    .WriteEnable(write_acc_en  ),
    .WriteAddr  (write_acc_addr),
    .WriteData  (write_acc_data)
  );

  // Softmax
  assign val = SoftmaxScalar;

  for (genvar i = 0; i < NumDiv; i++) begin
    ita_serdiv #(
      .WIDTH(DividerWidth)
    ) i_serdiv (
      .clk_i    (clk_i                 ),
      .rst_ni   (rst_ni                ),

      .op_a_i   (val                   ),
      .op_b_i   (DividerWidth'(div_inp)),
      .opcode_i ('0                    ),
      .in_vld_i (div_valid_inp[i]      ),
      .in_rdy_o (div_ready_inp[i]      ),
      .flush_i  (1'b0                  ),
      .out_vld_o(div_valid_oup[i]      ),
      .out_rdy_i(div_ready_oup[i]      ),
      .res_o    (div_oup[i]            )
    );
  end

endmodule


// ============================================================================
// ITA activation
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_activation.sv
// ============================================================================
// Copyright 2024 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51

module ita_activation
  import ita_package::*;
  (
    input logic clk_i,
    input logic rst_ni,
    input gelu_const_t b_i,
    input gelu_const_t c_i,
    input requant_mode_e requant_mode_i,
    input requant_const_t requant_mult_i,
    input requant_const_t requant_shift_i,
    input requant_t requant_add_i,
    input activation_e activation_i,
    input activation_e activation_q2_i,
    input logic calc_en_i,
    input logic calc_en_q_i,
    input requant_oup_t  data_i,
    output requant_oup_t data_o
  );

  requant_oup_t data_q1, data_q2, data_q3, data_q4;
  activation_e activation_q3, activation_q4;
  oup_t gelu_out, requant_in;
  requant_oup_t relu_out, requant_out;
  logic calc_en_q2, calc_en_q3;

  ita_requantizer i_requantizer (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .mode_i(requant_mode_i),
    .eps_mult_i(requant_mult_i),
    .right_shift_i(requant_shift_i),
    .add_i({N{requant_add_i}}),
    .calc_en_i(calc_en_q2),
    .calc_en_q_i(calc_en_q3),
    .result_i(requant_in),
    .requant_oup_o(requant_out)
  );

  generate
    for (genvar i = 0; i < N; i++) begin: relu_instances
      ita_relu i_relu (
        .data_i((calc_en_q2 && activation_q2_i == Relu) ? data_q2[i] : '0),
        .data_o(relu_out[i])
      );
    end
  endgenerate

  generate
    for (genvar i = 0; i < N; i++) begin: gelu_instances
      ita_gelu i_gelu (
        .clk_i(clk_i),
        .rst_ni(rst_ni),
        .b_i(b_i),
        .c_i(c_i),
        .calc_en_i(calc_en_i),
        .calc_en_q_i(calc_en_q_i),
        .data_i((calc_en_i && activation_i == Gelu) ? data_i[i] : '0),
        .data_o(gelu_out[i])
      );
    end
  endgenerate

  always_comb begin
    case (activation_q2_i)
      Gelu: begin
        requant_in = gelu_out;
      end
      Relu: begin
        for (int i = 0; i < N; i++) begin
          requant_in[i] = {{(WO-WI){relu_out[i][WI-1]}}, relu_out[i]};
        end
      end
      default: begin
        requant_in = '0;
      end
    endcase
  end


  always_comb begin
    case (activation_q4)
      Gelu, Relu: begin
        data_o = requant_out;
      end
      default: begin
        data_o = data_q4;
      end
    endcase
  end

  always_ff @(posedge clk_i) begin
    if (rst_ni == 0) begin
      activation_q3 <= Identity;
      activation_q4 <= Identity;
      data_q1 <= '0;
      data_q2 <= '0;
      data_q3 <= '0;
      data_q4 <= '0;
      calc_en_q2 <= 0;
      calc_en_q3 <= 0;
    end else begin
      activation_q3 <= activation_q2_i;
      activation_q4 <= activation_q3;
      data_q1 <= data_i;
      data_q2 <= data_q1;
      data_q3 <= data_q2;
      data_q4 <= data_q3;
      calc_en_q2 <= calc_en_q_i;
      calc_en_q3 <= calc_en_q2;
    end
  end
endmodule

// ============================================================================
// ITA requantizer
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_requantizer.sv
// ============================================================================
// Copyright 2020 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51


module ita_requantizer
  import ita_package::*;
(
  input  logic           clk_i        ,
  input  logic           rst_ni       ,
  input  requant_mode_e  mode_i       ,
  input  requant_const_t eps_mult_i   ,
  input  requant_const_t right_shift_i,
  input  logic           calc_en_i    ,
  input  logic           calc_en_q_i  ,
  input  oup_t           result_i     ,
  input  requant_oup_t   add_i        ,
  output requant_oup_t   requant_oup_o
);

  logic signed [      WO:0]             mult_signed  ;
  logic signed [EMS+WO:0]               product      ;
  logic signed [EMS+WO:0]               shifted_added;
  logic signed [     N-1:0][EMS+WO-1:0] shifted_d, shifted_q;
  requant_oup_t                         add_q1, requant_oup_d, requant_oup_q;

  assign requant_oup_o   = requant_oup_q;


  always_comb begin
    shifted_d     = '0;
    requant_oup_d = '0;
    product       = '0;
    shifted_added = '0;

    for (int i = 0; i < N; i++) begin
      if (mode_i === Unsigned) begin
        mult_signed = {1'b0, result_i[i]};
      end else begin
        mult_signed = signed'(result_i[i]);
      end
      if (calc_en_i) begin
        product = signed'({1'b0,eps_mult_i}) * signed'(mult_signed);
        shifted_d[i] = product >>> right_shift_i;

        // Perform rounding half away from zero
        if ( (right_shift_i > 0) & (product[right_shift_i-1]) ) begin
          shifted_d[i] = (product >>> right_shift_i) + 1;
        end
      end
      if (calc_en_q_i) begin
        shifted_added    = shifted_q[i] + (EMS+WO)'(signed'(add_q1[i]));
        requant_oup_d[i] = shifted_added[WI-1:0];
        if (~shifted_added[EMS+WO-1] & (|(shifted_added[EMS+WO-2:WI-1]))) begin
          requant_oup_d[i]       = '1;
          requant_oup_d[i][WI-1] = 1'b0; // sat+
        end
        else if (shifted_added[EMS+WO-1] & (|(~shifted_added[EMS+WO-2:WI-1]))) begin
          requant_oup_d[i]       = '0;
          requant_oup_d[i][WI-1] = 1'b1; // sat-
        end
      end
    end
  end

  always_ff @(posedge clk_i, negedge rst_ni) begin
    if (!rst_ni) begin
      shifted_q     <= '0;
      requant_oup_q <= '0;
    end else begin
      shifted_q     <= shifted_d;
      requant_oup_q <= requant_oup_d;
    end
  end

  always_ff @(posedge clk_i, negedge rst_ni) begin
    if (!rst_ni) begin
      add_q1         <= '0;
    end else begin
      add_q1         <= add_i;
    end
  end
endmodule


// ============================================================================
// ITA requantization controller
// Source: /pool0/pmcewen/rsgvm13dir/ctc_chipyard/chipyard/generators/ITA/src/main/resources/vsrc/ita_requantization_controller.sv
// ============================================================================
// Copyright 2020 ETH Zurich and University of Bologna.
// Solderpad Hardware License, Version 0.51, see LICENSE for details.
// SPDX-License-Identifier: SHL-0.51


module ita_requatization_controller
  import ita_package::*;
(
  input step_e requantizer_step_i,
  input ctrl_t ctrl_i,
  output requant_const_t requant_mult_o,
  output requant_const_t requant_shift_o,
  output requant_t requant_add_o,
  output requant_mode_e requant_mode_o,
  output requant_const_t activation_requant_mult_o,
  output requant_const_t activation_requant_shift_o,
  output requant_t activation_requant_add_o,
  output requant_mode_e activation_requant_mode_o
);
  logic [$clog2(N_REQUANT_CONSTS)-1:0] constant_idx;

  always_comb begin
    case (requantizer_step_i)
      Q: constant_idx = 0;
      K: constant_idx = 1;
      V: constant_idx = 2;
      QK: constant_idx = 3;
      AV: constant_idx = 4;
      OW: constant_idx = 5;
      F1: constant_idx = 6;
      F2: constant_idx = 7;
      default: constant_idx = 0;
    endcase
  end

  assign requant_mult_o = ctrl_i.eps_mult[constant_idx];
  assign requant_shift_o = ctrl_i.right_shift[constant_idx];
  assign requant_add_o = ctrl_i.add[constant_idx];
  assign activation_requant_mult_o = ctrl_i.activation_requant_mult;
  assign activation_requant_shift_o = ctrl_i.activation_requant_shift;
  assign activation_requant_add_o = ctrl_i.activation_requant_add;
  assign requant_mode_o = requant_mode_e'(REQUANT_MODE);
  assign activation_requant_mode_o = requant_mode_e'(REQUANT_MODE);
 endmodule


